from pathlib import Path
import json,hashlib
P=Path(__file__).resolve().parent;R=P.parent.parent;OUT=R/'output/bill-carry-start-east-preview'
d=json.loads((OUT/'journeys.json').read_text(encoding='utf-8'));v=json.loads((OUT/'validation.json').read_text(encoding='utf-8'));assert v['passed'] and d['failures']==0
html='''<!doctype html><meta charset="utf-8"><title>Bill first-step bridge</title><style>body{background:#182932;color:#dde8e9;font:16px system-ui;margin:24px}canvas{background:#22343e;max-width:100%;border:1px solid #536770}button,a{margin-right:12px;color:inherit}button{background:#344952;padding:8px;border:1px solid #71838b}</style><h1>Bill — first step after turning</h1><p>East-facing bridge, bare and helmet. New lower-body poses open the stance gradually while retaining Bill's master head, suit, hands and case.</p><p>Unselected art and movement preview. The carrying loop, remaining directions and saved-game handoffs still need polish and validation.</p><button id="pause">Pause</button><button id="restart">Restart</button><label>Height <select id="height"><option value="82">82</option><option value="27">27</option><option value="148">148</option></select></label><label> Time <input id="time" type="number" min="0" max="1.4" step="0.05" value="1.0" style="width:70px"></label><p id="clock"></p><canvas width="1000" height="1100"></canvas><p><a href="../bill-carry-turn-east-south-motion-v3/workshop-review.html">Station movement check</a><a href="candidate-review.png">Full source poses</a></p><script>
const data=RECORDS,journeys=data.journeys.filter(j=>j.reverse),images={},canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d');let paused=false,started=performance.now(),held=0;
document.querySelector('#pause').onclick=()=>{if(!paused){held=performance.now()-started;paused=true}else{started=performance.now()-held;paused=false}document.querySelector('#pause').textContent=paused?'Play':'Pause'};document.querySelector('#restart').onclick=()=>{started=performance.now();held=0};
document.querySelector('#time').oninput=()=>{held=Math.max(0,Math.min(1.4,Number(document.querySelector('#time').value)))*1000;paused=true;document.querySelector('#pause').textContent='Play'};
async function boot(){await Promise.all([...new Set(journeys.flatMap(j=>j.records.map(r=>r.sourceCapture)))].map(name=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[name]=im;resolve()};im.onerror=reject;im.src='../../output/bill-carry-start-east-preview/'+name})));requestAnimationFrame(draw)}
function draw(now){const t=Math.min(((paused?held:now-started)%2400)/1000,1.4),height=Number(document.querySelector('#height').value),s=height/148;ctx.fillStyle='#22343e';ctx.fillRect(0,0,1000,1100);ctx.font='17px system-ui';journeys.forEach((j,i)=>{const origin=j.records[0].foot,r=j.records.filter(r=>r.turnElapsed<=t).at(-1)||j.records[0],y=i*270+200,x=450+(r.foot[0]-origin[0])*height/(384*.17),py=y+(r.foot[1]-origin[1])*height/(384*.17);ctx.strokeStyle='#455b65';ctx.beginPath();ctx.moveTo(250,y);ctx.lineTo(900,y);ctx.stroke();ctx.fillStyle='#ffad59';ctx.fillRect(448,y-2,4,4);ctx.drawImage(images[r.sourceCapture],x-128*s,py-224*s,256*s,256*s);ctx.fillStyle='#dde8e9';ctx.fillText(`${j.candidate?'BRIDGE PREVIEW':'CURRENT'} · ${j.gear?'helmet':'bare'}`,12,i*270+32);ctx.fillText(r.starting?'first step':r.turning?'turn':'carrying walk',740,i*270+120)});document.querySelector('#clock').textContent=`${t.toFixed(2)}s — recorded motion repeats after a short hold`;requestAnimationFrame(draw)}boot();</script>'''
(P/'index.html').write_text(html.replace('RECORDS',json.dumps(d)),encoding='utf-8')
paths=[P/'bare-manifest.json',P/'helmet-manifest.json',P/'registration.json',P/'carry_start_preview_player.gd',R/'tests/test_bill_carry_start_east_preview.gd',OUT/'journeys.json',OUT/'corner-board.png']
e={'scope':d['scope'],'validation':v,'package':json.loads((P/'validation.json').read_text(encoding='utf-8')),'nativeChecks':d['checks'],'visualReview':'32actual displayed handoff source samples and12paired package poses reviewed. Gradual East stance improves abrupt turn-to-stride; legacy carry-loop cadence and body bob remain open.','normalSelectionChanged':False,'goalComplete':False,'hashTiming':'After native interval; dependency stability during run unmeasured.','inputHashes':{p.relative_to(R).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}}
(P/'runtime-evidence.json').write_text(json.dumps(e,indent=2)+'\n',encoding='utf-8');print('Built staged first-step replay; normal actor/selection unchanged')
